import {Meta, Party, Politician, Statement} from './types';

// Each file is fetched at most once per page load; the static files are
// regenerated by the pipeline, so there is nothing to invalidate client-side.
const cache = new Map<string, Promise<unknown>>();

export function fetchJson<T>(path: string): Promise<T> {
    if (!cache.has(path)) {
        const request = fetch(`${import.meta.env.BASE_URL}data/${path}`).then((res) => {
            if (!res.ok) throw new Error(`${res.status} ${res.statusText} (${path})`);
            return res.json();
        });
        // Drop failed requests so a retry can succeed.
        request.catch(() => cache.delete(path));
        cache.set(path, request);
    }
    return cache.get(path) as Promise<T>;
}

export const loadPoliticians = () => fetchJson<Politician[]>('politicians.json');
export const loadParties = () => fetchJson<Party[]>('parties.json');
export const loadMeta = () => fetchJson<Meta>('meta.json');
export const loadStatements = (politicianId: string) =>
    fetchJson<Statement[]>(`statements/${encodeURIComponent(politicianId)}.json`);

export const assetUrl = (path: string) => `${import.meta.env.BASE_URL}${path}`;

export function clearCache() {
    cache.clear();
}
